package com.example.ecommerce.servlet;
import com.example.ecommerce.dao.OrderDAO; import com.example.ecommerce.model.*; import javax.servlet.*; import javax.servlet.annotation.*; import javax.servlet.http.*; import java.io.IOException; import java.util.*;
@WebServlet({"/checkout","/my-orders"}) public class OrderServlet extends HttpServlet{
 @SuppressWarnings("unchecked") protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{User u=(User)req.getSession().getAttribute("user");if(u==null){resp.sendRedirect(req.getContextPath()+"/login");return;}List<CartItem> cart=(List<CartItem>)req.getSession().getAttribute("cart");if(cart==null||cart.isEmpty()){resp.sendRedirect(req.getContextPath()+"/cart");return;}new OrderDAO().createOrder(u.getId(),cart);req.getSession().removeAttribute("cart");req.getSession().setAttribute("message","Siparişiniz başarıyla oluşturuldu.");resp.sendRedirect(req.getContextPath()+"/my-orders");}catch(Exception e){throw new ServletException(e);}}
 protected void doGet(HttpServletRequest req,HttpServletResponse resp)throws ServletException,IOException{try{User u=(User)req.getSession().getAttribute("user");if(u==null){resp.sendRedirect(req.getContextPath()+"/login");return;}req.setAttribute("orders",new OrderDAO().findByUser(u.getId()));req.getRequestDispatcher("/WEB-INF/views/my-orders.jsp").forward(req,resp);}catch(Exception e){throw new ServletException(e);}}
}
